<?php require __DIR__.'/../config/config.php';$count=(int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn();$msg='';if($count===0&&$_SERVER['REQUEST_METHOD']==='POST'){$email=filter_var($_POST['email'],FILTER_VALIDATE_EMAIL);$pw=$_POST['password']??'';if(!$email||strlen($pw)<12)$msg='Use a valid email and password of at least 12 characters.';else{db()->prepare('INSERT INTO admins(email,password_hash) VALUES(?,?)')->execute([$email,password_hash($pw,PASSWORD_DEFAULT)]);$msg='Admin created. DELETE this setup_admin.php file now, then sign in at login.php.';}}?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="../assets/style.css"></head><body><main style="max-width:500px"><h1>Initial admin setup</h1><?php if($count>0):?><p>An admin already exists. Delete this file.</p><?php else:?><p><?=htmlspecialchars($msg)?></p><form method="post"><div class="field">Admin email<input name="email" type="email" required></div><div class="field">Strong password (12+ characters)<input name="password" type="password" minlength="12" required></div><button class="primary">Create admin</button></form><?php endif;?></main></body></html>
